property.value:
let $flip := function($op) { map { '<': '>', '<=': '>=', '>': '<', '>=': '<=' }($op) }
return
//ForStatement[ForUpdate][InfixExpression[@Operator = ('<', '<=', '>', '>=')]]
  [let $cond := InfixExpression[@Operator = ('<', '<=', '>', '>=')]
   return some $var in distinct-values(ForUpdate//VariableAccess/@Name)
     satisfies
       (let $left := exists($cond/*[1][self::VariableAccess][@Name = $var]),
            $right := exists($cond/*[2][self::VariableAccess][@Name = $var]),
            $op := if ($left) then string($cond/@Operator) else $flip(string($cond/@Operator)),
            $delta := function($u) {
              let $lit := $u/*[2]
              return if ($lit/self::NumericLiteral) then number($lit/@ValueAsDouble)
                     else if ($lit/self::UnaryExpression[@Operator = '-'][NumericLiteral]) then -number($lit/NumericLiteral/@ValueAsDouble)
                     else 0
            },
            $steps := ForUpdate//AssignmentExpression[@Operator = ('+=', '-=')][VariableAccess[1]/@Name = $var],
            $upward := ForUpdate//UnaryExpression[@Operator = '++'][VariableAccess/@Name = $var]
                     | $steps[@Operator = '+='][$delta(.) > 0] | $steps[@Operator = '-='][$delta(.) < 0],
            $downward := ForUpdate//UnaryExpression[@Operator = '--'][VariableAccess/@Name = $var]
                       | $steps[@Operator = '-='][$delta(.) > 0] | $steps[@Operator = '+='][$delta(.) < 0]
        return ($left != $right)
          and (exists($downward) and empty($upward) and $op = ('<', '<=') or exists($upward) and empty($downward) and $op = ('>', '>='))
          and empty($cond/VariableAccess[@Name = $var][pmd-java:typeIs('byte') or pmd-java:typeIs('short') or pmd-java:typeIs('char')])
          and empty(ForInit//PrimitiveType[@Kind = ('byte', 'short', 'char')])
          and empty(*[last()]//BreakStatement | *[last()]//ReturnStatement | *[last()]//ThrowStatement)
          and empty(*[last()]//VariableAccess[@Name = $var][@AccessType = 'WRITE']))]
